+const form = document.getElementById('support-form');
+const status = document.getElementById('form-status');
+const fields = [
+  {
+    input: document.getElementById('full-name'),
+    error: document.getElementById('full-name-error'),
+    message: 'Error: Enter your full name.',
+  },
+  {
+    input: document.getElementById('email-address'),
+    error: document.getElementById('email-address-error'),
+    message: 'Error: Enter a valid email address, like name@example.com.',
+  },
+];
+
+function setError(field, message) {
+  const { input, error } = field;
+  input.setAttribute('aria-invalid', 'true');
+  error.hidden = false;
+  error.textContent = message;
+  input.parentElement.classList.add('is-invalid');
+
+  const describedBy = input.getAttribute('aria-describedby') || '';
+  const ids = new Set(describedBy.split(/\s+/).filter(Boolean));
+  ids.add(error.id);
+  input.setAttribute('aria-describedby', Array.from(ids).join(' '));
+}
+
+function clearError(field) {
+  const { input, error } = field;
+  input.removeAttribute('aria-invalid');
+  error.hidden = true;
+  error.textContent = '';
+  input.parentElement.classList.remove('is-invalid');
+
+  const ids = (input.getAttribute('aria-describedby') || '')
+    .split(/\s+/)
+    .filter(Boolean)
+    .filter((id) => id !== error.id);
+
+  if (ids.length > 0) {
+    input.setAttribute('aria-describedby', ids.join(' '));
+  } else {
+    input.removeAttribute('aria-describedby');
+  }
+}
+
+function validateField(field) {
+  const value = field.input.value.trim();
+  const valid = field.input.validity.valid && value.length > 0;
+
+  if (valid) {
+    clearError(field);
+    return true;
+  }
+
+  setError(field, field.message);
+  return false;
+}
+
+fields.forEach((field) => {
+  field.input.addEventListener('input', () => {
+    if (field.input.value.trim().length === 0) {
+      return;
+    }
+
+    if (field.input.validity.valid) {
+      clearError(field);
+    }
+  });
+
+  field.input.addEventListener('blur', () => {
+    if (field.input.value.trim().length > 0) {
+      validateField(field);
+    }
+  });
+});
+
+form.addEventListener('submit', (event) => {
+  let firstInvalid = null;
+  const valid = fields.every((field) => {
+    const fieldValid = validateField(field);
+
+    if (!fieldValid && firstInvalid === null) {
+      firstInvalid = field.input;
+    }
+
+    return fieldValid;
+  });
+
+  if (!valid) {
+    event.preventDefault();
+    status.textContent = 'Please fix the highlighted fields and try again.';
+    firstInvalid.focus();
+    return;
+  }
+
+  event.preventDefault();
+  status.textContent = 'Thanks — your message has been prepared for sending.';
+  form.reset();
+  fields.forEach(clearError);
+});
*** End Patch
