+  const { input, error } = field;
+  input.removeAttribute('aria-invalid');
+  error.hidden = true;
+  error.textContent = '';
+  input.parentElement.classList.remove('is-invalid');
+
+  const ids = (input.getAttribute('aria-describedby') || '')
+    .split(/\s+/)
+    .filter(Boolean)
+    .filter((id) => id !== error.id);
